function EXTRA(R,ICON){
 /* hook: the fan on its wall bracket, and a shaft in its hole */
 ICON.mdFan=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${MD_box(0,0,380,170,{fill:'#FFFFFF',st:MD_GREY,sw:3,r:18})}
  ${MD_wall(16,16,40,138)}<rect x="56" y="48" width="190" height="12" rx="3" fill="${MD_STEEL}"/>${MD_L(60,112,160,54,MD_STEEL,9)}
  ${MD_L(226,60,226,96,MD_DARK,5)}<ellipse cx="226" cy="106" rx="20" ry="11" fill="${MD_LIGHT}" stroke="${MD_STEEL}" stroke-width="3"/>
  <path d="M206,106 L130,114 L130,102 Z" fill="${MD_GREY}"/><path d="M246,106 L322,114 L322,102 Z" fill="${MD_GREY}"/>
  ${MD_T(266,40,'8 kg fan',{fs:24,fw:800,fill:BLU})}${MD_T(110,152,'one steel bracket',{fs:22,fill:MD_GREY})}</g>`;
 ICON.mdHole=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${MD_box(0,0,380,170,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}
  <circle cx="96" cy="85" r="62" fill="${MD_LIGHT}" stroke="${MD_STEEL}" stroke-width="4"/><circle cx="96" cy="85" r="44" fill="#FFFFFF" stroke="${MD_DARK}" stroke-width="3"/>
  <circle cx="96" cy="85" r="39" fill="${MD_STEEL}"/>
  ${MD_T(180,62,'25 mm shaft',{fs:24,fw:800,fill:BLU})}${MD_T(180,96,'in a 25 mm hole',{fs:22,fill:MD_GREY})}${MD_T(180,130,'planned gap',{fs:24,fw:800,fill:ORG})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.mdLoop=(x,y)=>{const N=[['need',60,60],['spec',360,60],['test',360,250],['make',60,250]];let s='';
  s+=MD_arrow(118,60,300,60,BLU,4)+MD_arrow(360,90,360,218,BLU,4)+MD_arrow(300,250,120,250,BLU,4);
  s+=`<path d="M330,226 Q230,150 120,84" fill="none" stroke="${ORG}" stroke-width="4" stroke-dasharray="10 7"/>`+MD_T(180,176,'feedback',{fs:22,fw:800,fill:ORG});
  N.forEach(([t,cx,cy])=>{s+=MD_box(cx-56,cy-28,112,56,{fill:'#E7F5FF',st:BLU,sw:3,r:10})+MD_T(cx,cy+8,t,{fs:24,fw:800,a:'middle',fill:BLU})});
  return `<g transform="translate(${x-210} ${y-160})">${s}</g>`};
 ICON.mdRods=(x,y)=>{const R=[['mild steel',160.0,'0.628 kg',BLU],['aluminium',241.5,'0.326 kg',ORG],['alloy steel',83.3,'0.327 kg',GRN]];let s='';
  R.forEach(([n,A,m,col],i)=>{const cy=70+i*112,h=A/5;s+=MD_T(0,cy-h/2-10,n,{fs:24,fw:800,fill:col})+`<rect x="0" y="${cy-h/2}" width="250" height="${h}" rx="4" fill="${col}" fill-opacity=".8"/>`+MD_T(266,cy+9,m,{fs:26,fw:800,fill:MD_DARK})});
  return `<g transform="translate(${x-200} ${y-140})">${s}</g>`};
 ICON.mdFits=(x,y)=>{const zy=v=>200-v*4.2;let s=MD_L(0,zy(0),420,zy(0),MD_DARK,3)+MD_T(420,zy(0)+28,'zero line',{fs:22,a:'end',fill:MD_GREY});
  s+=`<rect x="20" y="${zy(21)}" width="100" height="${zy(0)-zy(21)}" fill="${BLU}" fill-opacity=".3" stroke="${BLU}" stroke-width="3"/>`+MD_T(70,zy(21)-10,'H7',{fs:24,fw:800,a:'middle',fill:BLU});
  [['g6',-20,-7,GRN],['k6',2,15,ORG],['p6',22,35,PUR]].forEach(([n,lo,hi,col],i)=>{const x0=150+i*92;s+=`<rect x="${x0}" y="${zy(hi)}" width="70" height="${zy(lo)-zy(hi)}" fill="${col}" fill-opacity=".3" stroke="${col}" stroke-width="3"/>`+MD_T(x0+35,(lo<0?zy(lo)+28:zy(hi)-10),n,{fs:24,fw:800,a:'middle',fill:col})});
  return `<g transform="translate(${x-210} ${y-150})">${s}</g>`};
}
